// Entreno v0.5.1 · módulo comprimido (gzip+base64) para recurso en línea de Lovelace
const D="",N=255457,C=1230908664;
const fail=(m)=>{if(!customElements.get("entreno-panel"))customElements.define("entreno-panel",class extends HTMLElement{setConfig(){}getCardSize(){return 3}connectedCallback(){this.style.cssText="display:block;padding:16px;border-radius:16px;background:var(--card-background-color,#15181D);color:var(--error-color,#FF5C5C);font-family:sans-serif";this.textContent="Entreno no se pudo cargar: "+m}});};
try{
const b=Uint8Array.from(atob(D),c=>c.charCodeAt(0));
const t=await new Response(new Blob([b]).stream().pipeThrough(new DecompressionStream("gzip"))).text();
let h=0;for(let i=0;i<t.length;i++)h=(h*31+t.charCodeAt(i))>>>0;
if(t.length!==N||h!==C)throw new Error("el codigo llego incompleto, vuelve a registrar el recurso");
const u=URL.createObjectURL(new Blob([t],{type:"text/javascript"}));
await import(u);URL.revokeObjectURL(u);
}catch(e){fail(e.message);}
